-- CRL-2026-11-02.1. Additive schema; preserve assessment evidence and old revisions.
ALTER TABLE public.users ADD COLUMN profile_photo text;
ALTER TABLE public.global_school_years ADD COLUMN deleted_at timestamptz;
CREATE OR REPLACE FUNCTION crl_private.provision_global_school_year() RETURNS trigger
 LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(177631,3);
 IF TG_TABLE_NAME='global_school_years' THEN
  IF NEW.deleted_at IS NULL THEN
   INSERT INTO public.school_years(id,teacher_id,start_year,label,created_at)
   SELECT gen_random_uuid(),u.id,NEW.start_year,NEW.label,now() FROM public.users u
   WHERE u.role='teacher' AND NOT EXISTS (SELECT 1 FROM public.school_years y WHERE y.teacher_id=u.id AND y.start_year=NEW.start_year AND y.deleted_at IS NULL);
  END IF;
 ELSIF NEW.role='teacher' THEN
  INSERT INTO public.school_years(id,teacher_id,start_year,label,created_at)
  SELECT gen_random_uuid(),NEW.id,g.start_year,g.label,now() FROM public.global_school_years g
  WHERE g.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM public.school_years y WHERE y.teacher_id=NEW.id AND y.start_year=g.start_year AND y.deleted_at IS NULL);
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION crl_private.provision_global_school_year() FROM PUBLIC,anon,authenticated;
DROP TRIGGER provision_year_for_all_teachers ON public.global_school_years;
CREATE TRIGGER provision_year_for_all_teachers AFTER INSERT OR UPDATE OF deleted_at ON public.global_school_years
 FOR EACH ROW EXECUTE FUNCTION crl_private.provision_global_school_year();
