$::jsonb;
 p public."AssessmentPeriod"; old_id uuid; old_version integer; new_id uuid; expected jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(177631,1);
 FOREACH p IN ARRAY ARRAY['BoSY','MoSY','EoSY']::public."AssessmentPeriod"[] LOOP
  expected := pool->p::text;
  SELECT r.id,r.version INTO old_id,old_version FROM public.assessment_library_heads h
   JOIN public.assessment_library_revisions r ON r.id=h.revision_id WHERE h.period=p;
  IF old_id IS NOT NULL AND (SELECT rows=expected FROM public.assessment_library_revisions WHERE id=old_id) THEN CONTINUE; END IF;
  IF old_version IS NOT NULL AND old_version<>1 THEN RAISE EXCEPTION 'Catalogue changed. Review the repair before retrying.'; END IF;
  INSERT INTO public.assessment_library_revisions(period,version,rows)
   VALUES(p,coalesce(old_version,0)+1,expected) RETURNING id INTO new_id;
  INSERT INTO public.assessment_library_heads(period,revision_id) VALUES(p,new_id)
   ON CONFLICT(period) DO UPDATE SET revision_id=EXCLUDED.revision_id;
 END LOOP;
END $repair$;
-- Seven elapsed days based on authoritative event time, not last edit time.
-- Archive/backup retention jobs and evidence are unchanged.
CREATE INDEX admin_audit_recent_page_idx ON public.admin_audit_events(occurred_at DESC,id DESC);
CREATE FUNCTION crl_private.expire_audit_events() RETURNS integer
 LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $$
DECLARE removed integer;
BEGIN
 WITH doomed AS (SELECT id FROM public.admin_audit_events
  WHERE occurred_at <= (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')-interval '7 days'
  ORDER BY occurred_at LIMIT 2000 FOR UPDATE SKIP LOCKED)
 DELETE FROM public.admin_audit_events e USING doomed d WHERE e.id=d.id;
 GET DIAGNOSTICS removed=ROW_COUNT;
 RETURN removed;
END $$;
REVOKE ALL ON FUNCTION crl_private.expire_audit_events() FROM PUBLIC,anon,authenticated;
DELETE FROM public.admin_audit_events WHERE occurred_at <= (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')-interval '7 days';
SELECT cron.schedule('crl-expire-audit-events','* * * * *','SELECT crl_private.expire_audit_events()');
